evidence.original_sql:
DELETE FROM users_aud
WHERE ctid IN (
    SELECT ctid
    FROM (
        SELECT
            ctid,
            ROW_NUMBER() OVER (PARTITION BY email ORDER BY rev ASC, id ASC) as rn
        FROM users_aud
    ) t
    WHERE t.rn > 1
);
ALTER TABLE users_aud ADD CONSTRAINT users_aud_email_unique UNIQUE (email);

